DROP TABLE IF EXISTS games;
CREATE TABLE games (
            game_id    TEXT PRIMARY KEY,
            date_from  TEXT,
            date_to    TEXT,
            has_wide   INTEGER DEFAULT 0,
            has_cohort INTEGER DEFAULT 0,
            has_fdr    INTEGER DEFAULT 0
        );

