DROP TABLE IF EXISTS segment_cross;
CREATE TABLE segment_cross (
            game_id       TEXT,
            day_seg       TEXT,
            spin_seg      TEXT,
            player_count  INTEGER,
            player_pct    REAL,
            total_bet     REAL,
            bet_pct       REAL,
            avg_bet_per_player REAL,
            PRIMARY KEY (game_id, day_seg, spin_seg)
        );

